const inp = $json || {};
const raw = (inp.raw_value === undefined || inp.raw_value === null) ? "" : String(inp.raw_value).trim();
return [{ json: {
  raw_value: raw,
  attribute_type: inp.attribute_type || "",
  current_canonical_id: inp.current_canonical_id || "",
  current_confidence: (inp.current_confidence === undefined ? 0 : inp.current_confidence),
  taxonomy_version: inp.taxonomy_version || "v1"
} }];

const p = $("Prepare").first().json;
const rows = $("Get Candidates").all().map(function (i) { return i.json; }).filter(function (r) { return r && r.canonical_id; });
const candidates = rows.map(function (r) { return { canonical_id: r.canonical_id, canonical_value: r.canonical_value }; });
const allowedIds = candidates.map(function (c) { return c.canonical_id; });
const sys = "You map a raw product attribute value to exactly one canonical taxonomy id from a provided list. Respond ONLY with a compact JSON object: {\"canonical_id\":<id or \"none\">,\"confidence\":<0-1 float>,\"rationale\":<short string>}. You MUST pick an id from the allowed list or \"none\".";
const user = "attribute_type: " + p.attribute_type + "\nraw_value: " + p.raw_value + "\nallowed_candidates: " + JSON.stringify(candidates);
const body = {
  model: "gpt-4o-mini",
  messages: [ { role: "system", content: sys }, { role: "user", content: user } ],
  temperature: 0,
  response_format: { type: "json_object" }
};
return [{ json: {
  raw_value: p.raw_value,
  attribute_type: p.attribute_type,
  taxonomy_version: p.taxonomy_version,
  allowed_ids: allowedIds,
  candidates: candidates,
  body_json: JSON.stringify(body)
} }];

const ctx = $("Build Prompt").first().json;
const allowed = ctx.allowed_ids || [];
const candidates = ctx.candidates || [];
const resp = $json || {};
let content = "";
try {
  content = resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : "";
} catch (e) { content = ""; }
let parsed = {};
try { parsed = JSON.parse(content); } catch (e) { parsed = {}; }
let id = parsed.canonical_id || "none";
if (id !== "none" && allowed.indexOf(id) === -1) { id = "none"; }
const found = candidates.find(function (c) { return c.canonical_id === id; });
const status = id === "none" ? "ai_none" : "ai_suggested";
return [{ json: {
  raw_value: ctx.raw_value,
  attribute_type: ctx.attribute_type,
  suggested_canonical_id: id === "none" ? "" : id,
  suggested_value: found ? found.canonical_value : "",
  ai_confidence: (parsed.confidence === undefined || parsed.confidence === null) ? 0 : parsed.confidence,
  rationale: parsed.rationale || "",
  status: status
} }];

