return [{ json: {
  raw_value: ctx.raw_value,
  attribute_type: ctx.attribute_type,
  suggested_canonical_id: "",
  suggested_value: "",
  ai_confidence: 0,
  rationale: "OpenAI call failed or node disabled",
  status: "ai_error"
} }];

