return [{ json: {
  raw_value: p.raw_value,
  attribute_type: p.attribute_type,
  suggested_canonical_id: "",
  suggested_value: "",
  ai_confidence: 0,
  rationale: "empty raw_value; no AI call made",
  status: "ai_none"
} }];
